### Option 1: Python Script (Automatic File Organizer)
If you have a messy "Downloads" or "Desktop" folder, this Python script will automatically scan the folder and organize your files into neat subfolders (Images, Documents, Audio, etc.) based on their file extensions.

```python
import os
import shutil

def organize_folder(folder_path):
    # Define the file types and their corresponding folder names
    file_types = {
        'Images': ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.svg'],
        'Documents': ['.pdf', '.docx', '.doc', '.txt', '.xlsx', '.pptx'],
        'Audio': ['.mp3', '.wav', '.aac', '.m4a'],
        'Video': ['.mp4', '.mkv', '.avi', '.mov'],
        'Archives': ['.zip', '.rar', '.tar', '.gz']
    }

    # Change directory to the target folder
    os.chdir(folder_path)

    # Loop through all files in the directory
    for file in os.listdir():
        # Skip directories
        if os.path.isdir(file):
            continue

        # Get the file extension
        file_name, file_ext = os.path.splitext(file)
        file_ext = file_ext.lower()

        # Find the correct folder for this file type
        moved = False
        for folder_name, extensions in file_types.items():
            if file_ext in extensions:
                # Create the folder if it doesn't exist
                if not os.path.exists(folder_name):
                    os.makedirs(folder_name)

                # Move the file
                shutil.move(file, os.path.join(folder_name, file))
                print(f"Moved: {file} -> {folder_name}/")
                moved = True
                break

        # If the file type is unknown, move it to 'Others'
        if not moved:
            if not os.path.exists('Others'):
                os.makedirs('Others')
            shutil.move(file, os.path.join('Others', file))
            print(f"Moved: {file} -> Others/")

if __name__ == "__main__":
    # Replace this with the path of the folder you want to clean up
    target_folder = input("Enter the full path of the folder to organize: ")

    if os.path.exists(target_folder):
        organize_folder(target_folder)
        print("\n🎉 Folder organized successfully!")
    else:
        print("❌ Invalid folder path. Please try again.")
```

